-- Completa a CATEGORIA dos produtos da Jota 2 que estao sem categoria, usando a categoria da Jota 3
-- (mesmo codigo; ou mesmo nome, pra produto sem codigo). Cria a categoria na Jota 2 se nao existir.
-- Nunca troca a categoria de produto que ja tem uma. Pode rodar mais de uma vez.
SET NAMES utf8mb4;
SELECT COUNT(*) AS sem_categoria_antes FROM produtos WHERE padaria_id = 2 AND ativo = 1 AND categoria_id IS NULL;
INSERT INTO categorias (padaria_id, nome) SELECT 2, 'ADICIONAIS' WHERE NOT EXISTS (SELECT 1 FROM categorias WHERE padaria_id = 2 AND nome = 'ADICIONAIS');
UPDATE produtos SET categoria_id = (SELECT id FROM (SELECT MIN(id) AS id FROM categorias WHERE padaria_id = 2 AND nome = 'ADICIONAIS') x) WHERE padaria_id = 2 AND categoria_id IS NULL AND codigo_barras IN ('262', '307', '311', '436', '483', '504', '505', '777', '8094', '8095', '8096');
